export async function createChapterProposalExtractionRequest(_sessionId:string,_input:{idempotencyKey:string;createdBy?:string}):Promise<ChapterProposalExtractionRequest>{throw new NewDesignError("请使用本章专属受控 AI 提取入口；旧任意任务合同不能生成结算清单。",503);}
export async function ingestChapterProposalExtractionResult(_requestId:string,_input:{attemptId:string;items:ChapterSettlementDraft[];idempotencyKey:string;createdBy?:string}):Promise<ChapterSettlementWorkspace>{throw new NewDesignError("AI 候选必须通过专属执行凭证和正式字段校验导入，旧入口不接受结果。",409);}

export async function getChapterBodySwitchImpactContract(sessionId:string):Promise<ChapterBodySwitchImpactContract>{const workspace=await getChapterSettlementWorkspace(sessionId);if(workspace.session.status!=="impact_review_required")throw new NewDesignError("该采用确认不需要正文切换影响预览。",409);const pool=await getNewDesignPool(),checkpoint=(await pool.query(`WITH ${settlementRecordCtes.chapter_stable_checkpoints}
SELECT * FROM chapter_stable_checkpoints WHERE chapter_document_id=$1 AND status='stable' ORDER BY created_at DESC LIMIT 1`,[workspace.session.chapterDocumentId])).rows[0],dependencies=checkpoint?await pool.query(`WITH RECURSIVE ${settlementRecordCtes.dependency_resource_states},
downstream(resource_id,depth,path) AS (SELECT edge.derived_resource_id,1,ARRAY[edge.source_resource_id,edge.derived_resource_id] FROM new_design.dependency_resources source JOIN new_design.dependency_edges edge ON edge.source_resource_id=source.id AND edge.status='active' WHERE source.book_id=$1 AND source.resource_kind='chapter_settlement' AND source.exact_version_id=$2 UNION ALL SELECT edge.derived_resource_id,downstream.depth+1,downstream.path||edge.derived_resource_id FROM downstream JOIN new_design.dependency_edges edge ON edge.source_resource_id=downstream.resource_id AND edge.status='active' WHERE NOT edge.derived_resource_id=ANY(downstream.path) AND downstream.depth<99) SELECT DISTINCT ON(resource.id) resource.resource_kind,resource.stable_object_id,resource.exact_version_id,CASE WHEN state.state IN ('stale','invalid','needs_review','recompute_pending','recomputing') THEN state.updated_at END invalidated_at FROM downstream JOIN new_design.dependency_resources resource ON resource.id=downstream.resource_id LEFT JOIN dependency_resource_states state ON state.resource_id=resource.id ORDER BY resource.id,downstream.depth`,[workspace.session.bookId,checkpoint.settlement_id]):{rows:[]};return{sessionId,chapterDocumentId:workspace.session.chapterDocumentId,oldBody:workspace.priorBody,newBody:workspace.candidate,oldSettlementId:checkpoint?String(checkpoint.settlement_id):null,oldCheckpoint:checkpoint?mapCheckpoint(checkpoint):null,downstreamDependencies:dependencies.rows.map(row=>({resourceKind:String(row.resource_kind),stableKey:String(row.stable_object_id),currentVersionId:String(row.exact_version_id),invalidatedAt:row.invalidated_at?iso(row.invalidated_at):null})),executionAllowed:false,generatedAt:new Date().toISOString()};}

export async function getNextChapterStableContext(bookId:string,chapterCardId:string):Promise<NextChapterStableContext>{
  const client=await(await getNewDesignPool()).connect();
  try{
    await client.query("BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY");
    const result=await getNextChapterStableContextInTransaction(client,bookId,chapterCardId);
    await client.query("COMMIT");return result;
  }catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}
}
/** Read actual sources within the caller's consistent transaction. */
export async function getNextChapterStableContextInTransaction(client:PoolClient,bookId:string,chapterCardId:string):Promise<NextChapterStableContext>{
    const adoptedPlan=await getAdoptedChapterPlanContractInTransaction(client,bookId,chapterCardId);
    const target=assertFound((await client.query(`WITH ${settlementRecordCtes.planning_objects}
SELECT sort_order FROM planning_objects WHERE id=$1 AND book_id=$2 AND status='active'`,[adoptedPlan.planningObjectId,bookId])).rows[0],"目标章节没有已采用计划。");
    const checkpoint=(await client.query(`WITH ${settlementRecordCtes.chapter_stable_checkpoints}
SELECT checkpoint.* FROM chapter_stable_checkpoints checkpoint
      JOIN new_design.chapter_documents document ON document.id=checkpoint.chapter_document_id AND document.adopted_version_id=checkpoint.body_version_id
      JOIN new_design.chapter_settlements settlement ON settlement.id=checkpoint.settlement_id AND settlement.status='committed'
      WHERE checkpoint.book_id=$1 AND checkpoint.chapter_order<$2 AND checkpoint.status='stable' ORDER BY checkpoint.chapter_order DESC LIMIT 1`,[bookId,target.sort_order])).rows[0];
    let facts:Row[]=[],states:Row[]=[],knowledge:Row[]=[];
    if(checkpoint){
      const confirmed=(checkpoint.summary as {confirmed?:{facts?:string[];knowledge?:string[]}})?.confirmed;
      facts=(await client.query(`WITH ${settlementRecordCtes.canonical_facts},
${settlementRecordCtes.canonical_fact_evidence}
SELECT DISTINCT fact.id,fact.subject_card_id,fact.predicate,fact.value_json FROM canonical_facts fact
        JOIN canonical_fact_evidence evidence ON evidence.fact_id=fact.id AND evidence.stale_at IS NULL
        JOIN new_design.text_anchors anchor ON anchor.id=evidence.chapter_text_anchor_id AND anchor.status='active'
        WHERE fact.book_id=$1 AND fact.status='confirmed' AND anchor.chapter_document_id=$2 AND anchor.body_version_id=$3 AND fact.id=ANY($4::uuid[])`,[bookId,checkpoint.chapter_document_id,checkpoint.body_version_id,confirmed?.facts??[]])).rows;
      states=(await readCheckpointConfirmedStateChanges(client,checkpoint)).effective;
      knowledge=(await client.query(`WITH ${settlementRecordCtes.knowledge_state_changes},
${settlementRecordCtes.knowledge_state_proposal_versions}
SELECT change.id,change.holder_key,change.stance,change.claim_id FROM knowledge_state_changes change
        JOIN knowledge_state_proposal_versions version ON version.id=change.proposal_version_id
        JOIN new_design.text_anchors anchor ON anchor.id=version.text_anchor_id AND anchor.status='active'
        WHERE change.book_id=$1 AND version.chapter_document_id=$2 AND version.body_version_id=$3 AND change.status='active' AND change.id=ANY($4::uuid[]) ORDER BY change.sequence`,[bookId,checkpoint.chapter_document_id,checkpoint.body_version_id,confirmed?.knowledge??[]])).rows;
    }
    const result:NextChapterStableContext={bookId,chapterCardId,previousCheckpoint:checkpoint?mapCheckpoint(checkpoint):null,adoptedPlan,
      confirmedFacts:facts.map(row=>({id:String(row.id),subjectCardId:String(row.subject_card_id),predicate:String(row.predicate),value:row.value_json})),
      recentStateChanges:states.map(row=>({id:String(row.id),subjectId:String(row.subject_id),stateKey:String(row.state_key),afterValue:row.after_json})),
      knowledgeChanges:knowledge.map(row=>({id:String(row.id),holderKey:String(row.holder_key),stance:row.stance as NextChapterStableContext["knowledgeChanges"][number]["stance"],claimId:String(row.claim_id)})),
      sourceVersions:{bodyVersionId:checkpoint?String(checkpoint.body_version_id):null,settlementId:checkpoint?String(checkpoint.settlement_id):null,planningVersionId:adoptedPlan.planningVersionId},generatedAt:new Date().toISOString()};
    return result;
}
